namespace CheckoutPricing.Domain;

public static class ShippingFeePolicy
{
    private const int StandardFeeCents = 490;
    private const int ExpressFeeCents = 990;
    private const int FreeStandardFromCents = 5_000;

    public static int FeeCents(int payableCents, LoyaltyTier tier, bool express) =>
        express ? ExpressFeeCents(tier) : StandardFeeCents(payableCents, tier);

    private static int ExpressFeeCents(LoyaltyTier tier) =>
        tier == LoyaltyTier.Platinum ? 0 : ExpressFeeCents();

    private static int ExpressFeeCents() => ExpressFeeCentsValue;

    private static int StandardFeeCents(int payableCents, LoyaltyTier tier) =>
        IsStandardShippingFree(payableCents, tier) ? 0 : StandardFeeCentsValue;

    private static bool IsStandardShippingFree(int payableCents, LoyaltyTier tier) =>
        payableCents >= FreeStandardFromCents || tier is LoyaltyTier.Gold or LoyaltyTier.Platinum;
}
